static inline int life_popcount12(unsigned short mask) {
    int n = 0;
    for (int i = 0; i < 12; ++i)
        if (mask & (1u << i)) ++n;
    return n;
}

/* Semitone offset of the idx-th set bit, or -1. */
static inline int life_nth_degree_semitone(unsigned short mask, int idx) {
    for (int i = 0; i < 12; ++i) {
        if (mask & (1u << i)) {
            if (idx == 0) return i;
            --idx;
        }
    }
    return -1;
}

/* The inverse: which scale degree is nearest this MIDI note.

   Needed for note input - a played note has to land on a row, and rows are
   degrees. A note outside the scale snaps to the nearest degree rather than
   being dropped, so playing the black keys in a pentatonic still draws
   something instead of silently doing nothing. */
static inline int life_note_to_degree(int note, int root, unsigned short mask);

/* Map a scale degree to a MIDI note.

   `degree` may be negative or run past the top of the scale; it wraps into
   octaves. Returns a note clamped to 0..127. An empty mask falls back to
   chromatic so a corrupt save can never produce silence or a divide by zero. */
static inline int life_degree_to_note(int degree, int root, unsigned short mask) {
    if (mask == 0) mask = 0xFFF;
    int n = life_popcount12(mask);
    int octave = degree / n;
    int idx = degree % n;
    if (idx < 0) { idx += n; --octave; }  /* C truncates toward zero; we need floor */
    int note = root + octave * 12 + life_nth_degree_semitone(mask, idx);
    return note < 0 ? 0 : (note > 127 ? 127 : note);
}

static inline int life_note_to_degree(int note, int root, unsigned short mask) {
    if (mask == 0) mask = 0xFFF;
    int n = life_popcount12(mask);

    /* Start from the octave the note is in, then check the degrees around it -
       far cheaper than sweeping the whole range, and exact because
       life_degree_to_note is monotonic in the degree. */
    int rough = ((note - root) * n) / 12;
    int best = rough, best_d = 1 << 20;
    for (int d = rough - n - 1; d <= rough + n + 1; ++d) {
        int diff = life_degree_to_note(d, root, mask) - note;
        if (diff < 0) diff = -diff;
        if (diff < best_d) { best_d = diff; best = d; }
    }
    return best;
}

/* ===== src/voice.h ===== */
/* plinky-life - note lifecycle.

   Pure C. No Plinky API. Compiled directly by the desktop test harness.

   This owns the question of what is currently sounding and when it stops, and
   nothing else. It does not know about the automaton, and it does not know
   whether a note ends up on Plinky's internal synth or on a MIDI cable - the
   panel decides that by consuming the release list this produces.

   Stuck notes are the classic failure mode for a sequencer with a MIDI sink, so
   every path that stops a voice - mute, rate change, transport stop, panel
   unload - goes through voice_release_all(). There is exactly one way for a
   note to end. */

#define LIFE_MAX_HELD 16   /* SEL_ALL can sound a whole 16-row column at once */

typedef struct {
    unsigned char note;
    unsigned char vel;
    unsigned char active;
    int ticks_left;
} held_note_t;

typedef struct {
    held_note_t held[LIFE_MAX_HELD];
} voice_notes_t;

static inline void voice_notes_init(voice_notes_t *v) {
    for (int i = 0; i < LIFE_MAX_HELD; ++i) {
        v->held[i].note = 0;
        v->held[i].vel = 0;
        v->held[i].active = 0;
        v->held[i].ticks_left = 0;
    }
}

static inline int voice_num_held(const voice_notes_t *v) {
    int n = 0;
    for (int i = 0; i < LIFE_MAX_HELD; ++i) n += v->held[i].active ? 1 : 0;
    return n;
}

/* Start a note. Returns the slot, or -1 if all 16 are busy.

   Re-arming a note that is already sounding refreshes its countdown rather than
   allocating a second slot; two note-ons for one pitch would leave the second
   note-off orphaned on the MIDI side. */
static inline int voice_arm(voice_notes_t *v, int note, int vel, int ticks) {
    for (int i = 0; i < LIFE_MAX_HELD; ++i)
        if (v->held[i].active && v->held[i].note == (unsigned char)note) {
            v->held[i].ticks_left = ticks;
            v->held[i].vel = (unsigned char)vel;
            return i;
        }
    for (int i = 0; i < LIFE_MAX_HELD; ++i)
        if (!v->held[i].active) {
            v->held[i].note = (unsigned char)note;
            v->held[i].vel = (unsigned char)vel;
            v->held[i].active = 1;
            v->held[i].ticks_left = ticks;
            return i;
        }
    return -1;
}

/* Advance every countdown by `ticks`. Notes that expire are appended to
   `released` (which must have room for LIFE_MAX_HELD entries) and the count is
   returned. The caller is responsible for actually sending the note-offs. */
static inline int voice_tick(voice_notes_t *v, int ticks, unsigned char *released) {
    int n = 0;
    for (int i = 0; i < LIFE_MAX_HELD; ++i) {
        if (!v->held[i].active) continue;
        v->held[i].ticks_left -= ticks;
        if (v->held[i].ticks_left <= 0) {
            released[n++] = v->held[i].note;
            v->held[i].active = 0;
        }
    }
    return n;
}

/* Release everything immediately. The single exit path for a voice.
   `released` must have room for LIFE_MAX_HELD entries. */
static inline int voice_release_all(voice_notes_t *v, unsigned char *released) {
    int n = 0;
    for (int i = 0; i < LIFE_MAX_HELD; ++i) {
        if (!v->held[i].active) continue;
        released[n++] = v->held[i].note;
        v->held[i].active = 0;
    }
    return n;
}

/* How many notes a chord-playing voice may sound at once.

   `synth_voices` is the pool. Every audible melody voice is guaranteed one, so
   a chord can never starve a melody. Whatever is left is split between the
   voices playing chords - so a single chord voice with the melodies muted gets
   the whole pool.

   Always returns at least 1: a voice that is audible must be able to make a
   sound, even in a badly over-subscribed setup. */
static inline int voice_poly_budget(int synth_voices, int mono_count, int chord_count,
                                    int max_held) {
    if (chord_count < 1) chord_count = 1;
    int spare = synth_voices - mono_count;
    int budget = spare / chord_count;
    if (budget < 1) budget = 1;
    if (budget > max_held) budget = max_held;
    return budget;
}

/* Note length is a percentage (10..100) of the voice's step interval. Always at
   least 1 tick, so a very short step at a low percentage still produces an
   audible note rather than a note-on immediately followed by a note-off. */
static inline int voice_length_ticks(int step_ticks, int length_percent) {
    if (length_percent < 10) length_percent = 10;
    if (length_percent > 100) length_percent = 100;
    /* 64-bit: step_ticks is microseconds and reaches 30,000,000, so
       step_ticks * 100 overflows a signed 32-bit int above ~21 seconds per
       step - which the slowest rate reaches below about 89 BPM. The overflow
       produced a negative length, releasing the note on the very next tick:
       a click instead of the longest note the panel can play. */
    int t = (int)(((int64_t)step_ticks * length_percent) / 100);
    return t < 1 ? 1 : t;
}

/* ===== src/ccmap.h ===== */
/* plinky-life - incoming MIDI CC map.

   Pure C. No Plinky API. Compiled directly by the desktop test harness.

   A contiguous block of controllers that mirrors the panel's own settings, so
   anything on the grid or the settings pages can also be driven from a DAW or a
   controller.

   Laid out BY PARAMETER, not by voice: the four voices' rates are four
   consecutive controllers, so a row of four knobs on a controller does the same
   thing to each voice. Grouping by voice would have put rate, rule, order,
   pitch, length and mute on one row instead, which is not how anyone reaches
   for four knobs.

   The block starts wherever the user puts it. It deliberately does NOT overlap
   the simulation CCs this panel SENDS (20..27) at the default base of 30, but
   nothing stops you moving it on top of them if you want the loopback. */

typedef enum {
    CC_KEY = 0,       /* root note */
    CC_SCALE,
    CC_OCTAVE,
    CC_GEN_RATE,      /* how often the world evolves */
    CC_FLOOR,         /* respawn population floor */
    CC_SEED_AMOUNT,
    CC_STALL,
    CC_CLEAR,         /* momentary: fires on the rising edge past halfway */
    CC_SEED_NOW,      /* momentary */
    CC_FREEZE,        /* level: >= halfway is frozen */
    CC_STEP,          /* momentary: one generation */

    CC_MUTE_1,        /* four consecutive, one per voice, and so on below */
    CC_MUTE_2, CC_MUTE_3, CC_MUTE_4,
    CC_RATE_1, CC_RATE_2, CC_RATE_3, CC_RATE_4,
    CC_RULE_1, CC_RULE_2, CC_RULE_3, CC_RULE_4,
    CC_ORDER_1, CC_ORDER_2, CC_ORDER_3, CC_ORDER_4,
    CC_PITCH_1, CC_PITCH_2, CC_PITCH_3, CC_PITCH_4,
    CC_LENGTH_1, CC_LENGTH_2, CC_LENGTH_3, CC_LENGTH_4,

    CC_PARAM_COUNT
} cc_param_t;

#define CC_IN_DEFAULT_BASE 30
#define CC_FIRST_PER_VOICE CC_MUTE_1

/* Which parameter a controller number addresses, or -1 for one we ignore.
   A base of 0 disables the whole block. */
static inline int cc_param_for_number(int cc, int base) {
    if (base <= 0) return -1;
    if (cc < base) return -1;
    int idx = cc - base;
    if (idx >= CC_PARAM_COUNT) return -1;
    return idx;
}

/* The highest controller number the block occupies, for a range check. */
static inline int cc_last_number(int base) { return base + CC_PARAM_COUNT - 1; }

/* Split 0..127 evenly across `count` options.

   127 must land on the last option - a controller sending its maximum has to be
   able to reach the top of the range, which a plain (v * count) / 128 does
   provide, but only because 127 * count / 128 == count - 1 for every count we
   use. The clamp makes that a guarantee rather than an arithmetic coincidence. */
static inline int cc_to_index(int value, int count) {
    if (count < 1) return 0;
    if (value < 0) value = 0;
    if (value > 127) value = 127;
    int i = (value * count) / 128;
    if (i >= count) i = count - 1;
    return i;
}

/* Map 0..127 onto an inclusive integer range. */
static inline int cc_to_range(int value, int lo, int hi) {
    if (hi < lo) return lo;
    return lo + cc_to_index(value, hi - lo + 1);
}

/* The CC value that means index `i` - the MIDDLE of that index's band.

   This is what makes two-way CC safe. Sending back the value we RECEIVED, or
   the bottom of the band, is not round-trip stable: with 29 scales, an incoming
   67 means scale 15, but 15 * 128 / 29 is 66, which reads back as scale 14. Echo
   that and the two ends walk away from each other. The midpoint is the unique
   choice where cc_to_index(cc_from_index(i, n), n) == i for every i.

   Given that, no channel juggling is needed to stop feedback: an echo of what we
   sent decodes to the value we already hold, changes nothing, and so sends
   nothing. The loop dies on the first pass. */
static inline int cc_from_index(int i, int count) {
    if (count < 1) return 0;
    if (i < 0) i = 0;
    if (i >= count) i = count - 1;
    int v = (i * 128 + 64) / count;
    if (v > 127) v = 127;
    return v;
}

static inline int cc_from_range(int value, int lo, int hi) {
    if (hi < lo) return 0;
    return cc_from_index(value - lo, hi - lo + 1);
}

/* Momentary controls fire on the rising edge through the midpoint, so a button
   that sends 127 then 0 fires once rather than twice. */
static inline int cc_is_press(int previous, int value) {
    return previous < 64 && value >= 64;
}

/* Which voice a per-voice parameter belongs to, or -1 if it is global. */
static inline int cc_voice_for_param(int param) {
    if (param < CC_FIRST_PER_VOICE || param >= CC_PARAM_COUNT) return -1;
    return (param - CC_FIRST_PER_VOICE) % 4;
}

/* Which group a per-voice parameter belongs to: 0 mute, 1 rate, 2 rule,
   3 order, 4 pitch, 5 length. -1 if it is global. */
static inline int cc_group_for_param(int param) {
    if (param < CC_FIRST_PER_VOICE || param >= CC_PARAM_COUNT) return -1;
    return (param - CC_FIRST_PER_VOICE) / 4;
}

/* ===== src/chance.h ===== */
/* plinky-life - conditional triggers, derived from the world.

   Pure C. No Plinky API. Compiled directly by the desktop test harness.

   The obvious way to do this is a per-step overlay you draw by hand. Here they
   are read off the cell the voice actually landed on instead, because the world
   is the thing that moves: a value drawn onto step 7 would be the only part of
   the panel that does not respond to what you are watching. A glider passing
   through a voice's path should audibly change its rhythm, and that only happens
   if the rhythm is a function of the cells.

   Each behaviour has a DEPTH of 0..100, and depth 0 is off. So one control both
   enables a behaviour and says how strongly it responds - there is no separate
   switch to forget.

   All four take the same shape: at depth 0 the behaviour never fires, at depth
   100 the world drives it fully. */

typedef struct {
    unsigned int rng;
    unsigned int pass;    /* how many times this voice has crossed the world */
} chance_state_t;

static inline void chance_reset(chance_state_t *c, unsigned int seed) {
    c->rng = seed ? seed : 0x6d2b79f5u;
    c->pass = 0;
}

static inline unsigned int chance_rand(chance_state_t *c) {
    unsigned int x = c->rng ? c->rng : 0x6d2b79f5u;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    c->rng = x;
    return x;
}

/* Does this note sound at all?

   Lonely cells get dropped, crowded ones always play. `neighbours` is 0..8, so
   a cell with 8 neighbours is certain at any depth and a cell with none is
   dropped in proportion to depth. At depth 0 everything fires. */
static inline int chance_should_fire(int depth, int neighbours, chance_state_t *c) {
    if (depth <= 0) return 1;
    if (neighbours < 0) neighbours = 0;
    if (neighbours > 8) neighbours = 8;
    if (depth > 100) depth = 100;

    int chance = 100 - (depth * (8 - neighbours)) / 8;
    if (chance >= 100) return 1;
    if (chance <= 0) return 0;
    return (int)(chance_rand(c) % 100u) < chance;
}

/* How many times to retrigger inside one step, 1..4.

   Crowding adds repeats, so a dense knot of cells rolls and a sparse line does
   not. Deterministic on purpose: ratchets that came and went at random would be
   impossible to play along with. */
static inline int chance_ratchets(int depth, int neighbours) {
    if (depth <= 0) return 1;
    if (neighbours < 0) neighbours = 0;
    if (neighbours > 8) neighbours = 8;
    if (depth > 100) depth = 100;

    int extra = (neighbours * depth * 3) / (8 * 100);
    if (extra > 3) extra = 3;
    return 1 + extra;
}

/* Hold the previous note instead of striking a new one.

   Only cells that were already alive last generation can tie - something that
   persisted is what a held note means. Cells born this generation always
   strike. */
static inline int chance_should_tie(int depth, int survived, chance_state_t *c) {
    if (depth <= 0 || !survived) return 0;
    if (depth > 100) depth = 100;
    return (int)(chance_rand(c) % 100u) < depth;
}

/* Play only every Nth crossing of the world, N = 1..4.

   The one behaviour here that is about TIME rather than the cells: it gives a
   voice a phrase longer than a single pass, which nothing else in the panel
   provides. */
static inline int chance_pass_divisor(int depth) {
    if (depth <= 0) return 1;
    if (depth > 100) depth = 100;
    return 1 + (depth * 3) / 100;
}

static inline int chance_pass_ok(int depth, const chance_state_t *c) {
    int n = chance_pass_divisor(depth);
    if (n <= 1) return 1;
    return (int)(c->pass % (unsigned int)n) == 0;
}

/* ===== src/panel.cpp ===== */

/* ---------------------------------------------------------------------------
   This file does NOT compile on its own. It has no #includes (they are banned
   in panel code) and only type-checks once the IDE injects the SDK headers.

   The pure logic lives in the src/ headers and is desktop-tested by harness/tests.c.
   `sh build/amalgamate.sh` splices those headers in ahead of this file to
   produce the single life.cpp that gets flashed.
   ------------------------------------------------------------------------- */

#define PANEL_PAD_COLOR WHITE

/* --- Palette --------------------------------------------------------------

   SYSTEM_NOTES.md section 4: the dim tiers are far dimmer than they look.
   WHITE is already LED_RGB(15,15,15), so DIMMEST(WHITE) lands at 3 of 31 and
   DIMMESTEST at 1 - effectively invisible, and a real source of "dead LED" bug
   reports. Every colour here is therefore written out explicitly. */

#define LIFE_COL_ALIVE      LED_RGB(11, 11, 11)
#define LIFE_COL_ALIVE_DIM  LED_RGB(3, 3, 3)     /* world under the action layer */
#define LIFE_COL_MODIFIER   LED_RGB(20, 0, 16)
#define LIFE_COL_ACTION     LED_RGB(0, 10, 12)
#define LIFE_COL_DANGER     LED_RGB(24, 2, 0)
#define LIFE_COL_OFF        LED_RGB(2, 2, 2)

/* The cell a voice just took. Deliberately NOT the voice's own colour: that put
   the note on the same hue as the column tint it sits in, which is why it read
   as playhead decoration rather than as a note.

   Magenta is the one hue in the world view with no green in it. Live cells are
   white, the four voice tints are red, green, blue and yellow, so nothing else
   can be mistaken for it. Which voice played it is already answered by the
   column it is standing in. */
#define LIFE_COL_TRIGGER     LED_RGB(29, 0, 29)
#define LIFE_COL_TRIGGER_DIM LED_RGB(8, 0, 8)

/* LED_RGB packs 5-bit channels as g<<24 | r<<16 | b<<8. `q` is 0..256. */
static inline uint32_t life_scale_col(uint32_t c, int q) {
    if (q <= 0) return 0;
    if (q > 256) q = 256;
    int g = (int)((c >> 24) & 31), r = (int)((c >> 16) & 31), b = (int)((c >> 8) & 31);
    return LED_RGB((r * q) >> 8, (g * q) >> 8, (b * q) >> 8);
}

static const uint32_t life_voice_dim[4] = {
    LED_RGB(7, 0, 0), LED_RGB(0, 7, 0), LED_RGB(0, 1, 10), LED_RGB(6, 4, 0),
};
